import{_ as t,o,a as i,b as r}from"./app.BGziXukh.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"原子操作","link":"/api/SIMD-API/tensor_api/atomic/atomic"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/atomic/atomic.md","filePath":"api/SIMD-API/tensor_api/atomic/atomic.md","lastUpdated":1794877794000}'),e={name:"api/SIMD-API/tensor_api/atomic/atomic.md"};function m(l,a,s,c,_,n){return o(),i("div",null,[...a[0]||(a[0]=[r('<div><article class="markdown-body"><h1>原子操作</h1><p>DMA（Direct Memory Access，直接内存访问单元）原子操作用于在数据搬运过程中对Global Memory上的已有数据执行原子读改写，再写入搬运结果。Tensor API提供以下接口配置后续目的地址为Global Memory的受支持搬运指令：</p><ul><li><strong><a href="set_atomic_add.html">set_atomic_add</a></strong>：将待搬运数据与Global Memory上的已有数据求和，并将结果写入Global Memory。</li><li><strong><a href="set_atomic_max.html">set_atomic_max</a></strong>：比较待搬运数据与Global Memory上的已有数据，将两者中的最大值写入Global Memory。</li><li><strong><a href="set_atomic_min.html">set_atomic_min</a></strong>：比较待搬运数据与Global Memory上的已有数据，将两者中的最小值写入Global Memory。</li><li><strong><a href="disable_dma_atomic.html">disable_dma_atomic</a></strong>：关闭DMA原子模式，避免原子配置影响后续搬运。</li></ul><p><code>set_atomic_add</code>、<code>set_atomic_max</code>和<code>set_atomic_min</code>通过模板参数指定参与原子操作的数据类型。</p><p>Scalar原子操作用于在Global Memory的指定地址上完成单个元素的原子读改写：</p><ul><li><strong><a href="atomic_add.html">atomic_add</a></strong>：执行原子加，并返回旧值。</li><li><strong><a href="atomic_sub.html">atomic_sub</a></strong>：执行原子减，并返回旧值。</li><li><strong><a href="atomic_min.html">atomic_min</a></strong>：执行原子取小，并返回旧值。</li><li><strong><a href="atomic_max.html">atomic_max</a></strong>：执行原子取大，并返回旧值。</li><li><strong><a href="atomic_inc.html">atomic_inc</a></strong>：执行原子递增，并返回旧值。</li><li><strong><a href="atomic_dec.html">atomic_dec</a></strong>：执行原子递减，并返回旧值。</li><li><strong><a href="atomic_and.html">atomic_and</a></strong>：执行原子按位与，并返回旧值。</li><li><strong><a href="atomic_or.html">atomic_or</a></strong>：执行原子按位或，并返回旧值。</li><li><strong><a href="atomic_xor.html">atomic_xor</a></strong>：执行原子按位异或，并返回旧值。</li><li><strong><a href="atomic_exch.html">atomic_exch</a></strong>：执行原子交换，并返回旧值。</li><li><strong><a href="atomic_cas.html">atomic_cas</a></strong>：执行原子比较交换，并返回旧值。</li></ul></article></div>',1)])])}const p=t(e,[["render",m]]);export{h as __pageData,p as default};
